    const MAX_CANVAS_SIDE = 16000;
    const MAX_FILES = 30;
    const OMIT = 'script, style, noscript, input, textarea, select, [data-ait-owned-ui], '
        + '.runner-code-run-btn, .runner-container, .formula-tooltip, .ait-highlight-action, '
